"""Resolve string constants referenced in main and identify callees."""
from capstone import *
import struct

PATH = "/usr/local/bin/csv_renamer"
data = open(PATH, "rb").read()

e_phoff = struct.unpack_from("<Q", data, 32)[0]
e_phentsize = struct.unpack_from("<H", data, 54)[0]
e_phnum = struct.unpack_from("<H", data, 56)[0]

loads = []
for i in range(e_phnum):
    off = e_phoff + i * e_phentsize
    p_type, p_flags, p_offset, p_vaddr, p_paddr, p_filesz, p_memsz, p_align = \
        struct.unpack_from("<IIQQQQQQ", data, off)
    if p_type == 1:
        loads.append((p_vaddr, p_offset, p_filesz))

def off_of(v):
    for va, off, fsz in loads:
        if va <= v < va + fsz:
            return off + (v - va)
    return None

def read_str(v):
    o = off_of(v)
    if o is None:
        return None
    end = data.find(b"\x00", o)
    return data[o:end]

def read_bytes(v, n):
    o = off_of(v)
    return data[o:o + n]

# --- Resolve constants from main disassembly ---
md = Cs(CS_ARCH_X86, CS_MODE_64)
md.detail = True

main_code_off = off_of(0x401740)
code = data[main_code_off:main_code_off + 0x140]

consts = {}
for ins in md.disasm(code, 0x401740):
    for opnd in ins.operands:
        if opnd.type == X86_OP_MEM and opnd.mem.base == X86_REG_RIP:
            target = ins.address + ins.size + opnd.mem.disp
            s = read_str(target)
            if s and len(s) > 0 and all(32 <= c < 127 for c in s):
                consts[ins.address] = (target, s)
        if opnd.type == X86_OP_IMM and ins.mnemonic == "lea":
            pass

print("RIP-relative string constants in main():")
for addr, (target, s) in sorted(consts.items()):
    print(f"  0x{addr:x} -> 0x{target:x}: {s!r}")

# Explicit targets computed by hand from the disassembly
targets = {
    "fmt (loop1 fprintf)": 0x401754 + 0x7e356,
    "string table (loop1)": 0x40175c + 0xa55c4,
    "snprintf fmt (loop2)": 0x4017ca + 0x7d846,
    "fopen mode (loop2)": 0x4017ae + 0x7d879,
    "fwrite content 1 (30B)": 0x4017b5 + 0x7fc0b,
    "fwrite content 2 (45B)": 0x4017bc + 0x7fc2c,
    "fwrite content 3 (45B)": 0x40182a + 0x7fbee,
}
print("\nHand-resolved targets:")
for label, v in targets.items():
    s = read_str(v)
    print(f"  {label}: 0x{v:x} = {s!r}")

# String table entries (76 pointers)
tbl = 0x40175c + 0xa55c4
o = off_of(tbl)
ptrs = struct.unpack_from("<76Q", data, o)
print(f"\nString table at 0x{tbl:x}: {len(ptrs)} pointers")
for i, p in enumerate(ptrs):
    s = read_str(p)
    print(f"  [{i:2d}] 0x{p:x}: {s!r}")

# Identify callee functions by size/first instructions
print("\nCallee first instructions:")
for func, name in [(0x41aa90, "0x41aa90 (fprintf_chk?)"), (0x41ab50, "0x41ab50 (snprintf_chk?)"),
                   (0x4051c0, "0x4051c0 (fopen?)"), (0x4052c0, "0x4052c0 (fwrite?)"),
                   (0x404e00, "0x404e00 (fclose?)"), (0x403e30, "0x403e30 (libc_start_main?)")]:
    o = off_of(func)
    c = data[o:o + 100]
    print(f"\n--- {name} ---")
    for ins in md.disasm(c, func):
        print(f"  0x{ins.address:x}: {ins.mnemonic} {ins.op_str}")
        if ins.address > func + 60:
            break
