"""Check .init_array/.fini_array for hidden startup code, and disassemble their targets."""
from capstone import *
from capstone.x86 import *
import struct

PATH = "/usr/local/bin/csv_renamer"
data = open(PATH, "rb").read()

e_phoff = struct.unpack_from("<Q", data, 32)[0]
e_phentsize = struct.unpack_from("<H", data, 54)[0]
e_phnum = struct.unpack_from("<H", data, 56)[0]
e_shoff = struct.unpack_from("<Q", data, 40)[0]
e_shentsize = struct.unpack_from("<H", data, 58)[0]
e_shnum = struct.unpack_from("<H", data, 60)[0]
e_shstrndx = struct.unpack_from("<H", data, 62)[0]

sections = []
for i in range(e_shnum):
    off = e_shoff + i * e_shentsize
    vals = struct.unpack_from("<IIQQQQIIQQ", data, off)
    sections.append(vals)

shstr_off, shstr_size = sections[e_shstrndx][4], sections[e_shstrndx][5]
shstr = data[shstr_off:shstr_off + shstr_size]
def name_at(off):
    end = shstr.find(b"\x00", off)
    return shstr[off:end].decode()

loads = []
for i in range(e_phnum):
    off = e_phoff + i * e_phentsize
    p_type, p_flags, p_offset, p_vaddr, p_paddr, p_filesz, p_memsz, p_align = \
        struct.unpack_from("<IIQQQQQQ", data, off)
    if p_type == 1:
        loads.append((p_vaddr, p_offset, p_filesz))

def off_of(v):
    for va, off, fsz in loads:
        if va <= v < va + fsz:
            return off + (v - va)
    return None

md = Cs(CS_ARCH_X86, CS_MODE_64)

for i in range(e_shnum):
    nm = name_at(sections[i][0])
    if nm in (".init_array", ".fini_array"):
        sh_offset, sh_size = sections[i][4], sections[i][5]
        n = sh_size // 8
        ptrs = struct.unpack_from(f"<{n}Q", data, sh_offset)
        print(f"{nm}: {n} entries -> {[hex(p) for p in ptrs]}")
        for p in ptrs:
            o = off_of(p)
            if o is None:
                print(f"  0x{p:x}: not in file (NOBITS/bss?)")
                continue
            print(f"--- disassembly of 0x{p:x} ---")
            for ins in md.disasm(data[o:o + 80], p):
                print(f"  0x{ins.address:x}: {ins.mnemonic} {ins.op_str}")
                if ins.mnemonic == "ret" or ins.mnemonic == "jmp":
                    break
